namespace sv_e441a110218040d484640046d7d6fd23.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (one per circuit) that holds theme state and notifies
/// all subscribers when values change.
/// </summary>
public sealed class ThemeService
{
    private Theme _theme = Theme.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public Theme CurrentTheme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Fired whenever theme or accent color changes.
    /// Interactive components subscribe in OnInitialized and
    /// call StateHasChanged in the handler.
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@* Interactive island that lives in the static MainLayout header.
   It subscribes to ThemeService so it re-renders on every change. *@
@rendermode InteractiveServer
@inject sv_e441a110218040d484640046d7d6fd23.Services.ThemeService ThemeSvc
@implements IDisposable

<span class="badge rounded-pill"
      style="background-color: @ThemeSvc.AccentColor; color: white;">
    @icon @ThemeSvc.CurrentTheme
</span>

@code {
    private string icon => ThemeSvc.CurrentTheme switch
    {
        sv_e441a110218040d484640046d7d6fd23.Services.Theme.Light => "☀️",
        sv_e441a110218040d484640046d7d6fd23.Services.Theme.Dark  => "🌙",
        _                                                        => "💻"
    };

    protected override void OnInitialized()
        => ThemeSvc.OnChange += StateHasChanged;

    public void Dispose()
        => ThemeSvc.OnChange -= StateHasChanged;
}

@* Quick toggle that can be placed anywhere (sidebar, toolbar, etc.).
   Must be rendered as an interactive island. *@
@rendermode InteractiveServer
@inject sv_e441a110218040d484640046d7d6fd23.Services.ThemeService ThemeSvc
@implements IDisposable

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        title="Current: @ThemeSvc.CurrentTheme — click to cycle">
    @icon
</button>

@code {
    private string icon => ThemeSvc.CurrentTheme switch
    {
        sv_e441a110218040d484640046d7d6fd23.Services.Theme.Light => "☀️",
        sv_e441a110218040d484640046d7d6fd23.Services.Theme.Dark  => "🌙",
        _                                                        => "💻"
    };

    private void CycleTheme()
    {
        ThemeSvc.CurrentTheme = ThemeSvc.CurrentTheme switch
        {
            sv_e441a110218040d484640046d7d6fd23.Services.Theme.Light  => sv_e441a110218040d484640046d7d6fd23.Services.Theme.Dark,
            sv_e441a110218040d484640046d7d6fd23.Services.Theme.Dark   => sv_e441a110218040d484640046d7d6fd23.Services.Theme.System,
            _                                                         => sv_e441a110218040d484640046d7d6fd23.Services.Theme.Light,
        };
    }

    protected override void OnInitialized()
        => ThemeSvc.OnChange += StateHasChanged;

    public void Dispose()
        => ThemeSvc.OnChange -= StateHasChanged;
}

@page "/settings"
@rendermode InteractiveServer
@inject sv_e441a110218040d484640046d7d6fd23.Services.ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var t in Enum.GetValues<sv_e441a110218040d484640046d7d6fd23.Services.Theme>())
            {
                <button class="btn @(t == ThemeSvc.CurrentTheme ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => ThemeSvc.CurrentTheme = t">
                    @t
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <input type="color" class="form-control form-control-color mb-3"
               value="@ThemeSvc.AccentColor"
               @onchange="OnColorChanged"
               title="Choose accent color" />

        <p>
            Current accent:
            <span class="badge" style="background-color: @ThemeSvc.AccentColor; color: white;">
                @ThemeSvc.AccentColor
            </span>
        </p>
    </div>
</div>

@code {
    private void OnColorChanged(ChangeEventArgs e)
    {
        ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    protected override void OnInitialized()
        => ThemeSvc.OnChange += StateHasChanged;

    public void Dispose()
        => ThemeSvc.OnChange -= StateHasChanged;
}

